content.content:
1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width,initial-scale=1">
6	<title>FirstRun: Docs that work (literally)</title>
7	<link rel="stylesheet" href="assets/site-nav.css">
8	<meta name="description" content="Docs break quietly, and a new user finds out first. Doc-test runs your quickstart in a clean container and proves the fix. Doc-audit finds the pages your code left behind.">
9	<meta name="color-scheme" content="light">
10	<script>document.documentElement.className="js"</script>
11	<meta property="og:type" content="website">
12	<meta property="og:title" content="FirstRun: Docs that work (literally).">
13	<meta property="og:description" content="Doc-test proves your quickstart works in a clean container. Doc-audit reads git history and finds stale docs pages.">
14	<meta property="og:image" content="assets/og-card-1200x630.jpg">
15	<meta name="twitter:card" content="summary_large_image">
16	<link rel="icon" href="assets/logo.svg" type="image/svg+xml">
17	<link rel="preconnect" href="https://fonts.googleapis.com">
18	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
19	<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700&family=Geist+Mono:wght@400;500;600&display=swap">
20	<style>
21	:root{
22	--bg:oklch(98.7% .003 255);--panel:oklch(99.8% .0015 255);--sunk:oklch(97.1% .005 255);--hover:oklch(96.2% .007 255);
23	--line:oklch(91.6% .007 255);--ink:oklch(22% .012 255);--mut:oklch(48% .013 255);
24	--test:oklch(55% .19 256);--test-d:oklch(47% .17 256);--test-bg:oklch(95.6% .026 256);
25	--audit:oklch(52% .2 295);--audit-d:oklch(45% .18 295);--audit-bg:oklch(95.8% .03 295);
26	--gold:oklch(72% .14 78);--gold-d:oklch(44% .09 65);--gold-bg:oklch(96.6% .035 85);
27	--ok:oklch(52% .14 150);--ok-d:oklch(45% .12 150);--ok-bg:oklch(96.4% .032 150);
28	--bad:oklch(53% .19 27);--bad-bg:oklch(96.6% .02 27);
29	--sh:0 1px 2px oklch(30% .02 255/.06);
30	--lift:0 1px 2px oklch(30% .03 256/.05),0 8px 24px -10px oklch(35% .06 256/.16),0 24px 56px -28px oklch(35% .06 256/.18);
31	--lift-h:0 2px 4px oklch(30% .03 256/.06),0 16px 36px -12px oklch(35% .07 256/.22),0 36px 72px -30px oklch(35% .07 256/.24);
32	--ease:cubic-bezier(.16,1,.3,1);--road:oklch(22% .012 255/.08);
33	--mono:"Geist Mono",ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
34	--pad:clamp(72px,10vw,128px);--link:var(--test-d)}
35	*{box-sizing:border-box;margin:0}
36	html{background:var(--bg);color:var(--ink);font-family:Geist,-apple-system,BlinkMacSystemFont,"SF Pro Text","Segoe UI",Roboto,sans-serif;-webkit-text-size-adjust:100%;scroll-behavior:smooth}
37	body{background:var(--bg);line-height:1.5;font-size:16px;-webkit-font-smoothing:antialiased}
38	html,body{overflow-x:clip}
39	code,pre,.mono{font-family:var(--mono)}
40	/* every link is underlined. Real buttons look like buttons and carry no underline. */
41	a{color:var(--link);text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:3px}
42	a:hover{text-decoration-thickness:2px}
43	:focus-visible{outline:2px solid var(--test);outline-offset:2px;border-radius:6px}
44	img{max-width:100%}
45	.wrap{max-width:1080px;margin:0 auto;padding:0 24px}
46	section{padding:var(--pad) 0 0}
47	h1{font-size:clamp(36px,5.6vw,64px);line-height:1.03;letter-spacing:-.045em;font-weight:700}
48	h2{font-size:clamp(30px,4.4vw,48px);line-height:1.06;letter-spacing:-.04em;font-weight:700;text-align:center;max-width:17em;margin:0 auto;text-wrap:balance}
49	h3{letter-spacing:-.025em}
50	.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;box-shadow:var(--lift)}
51	.ic{width:20px;height:20px;flex:none;display:inline-block}
52	/* motion: one fade and rise as a block enters, staggered inside a group */
53	html.js .rv{opacity:0;transform:translateY(22px);transition:opacity .9s var(--ease),transform .9s var(--ease)}
54	html.js .rv.in{opacity:1;transform:none}
55	/* buttons */
56	button,.btn{font:inherit;font-weight:600;font-size:15px;background:var(--test);color:oklch(99.5% .003 256);border:1px solid var(--test);border-radius:12px;padding:0 22px;cursor:pointer;min-height:46px;white-space:nowrap;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:8px;transition:background .15s,transform .4s var(--ease)}
57	button:hover,.btn:hover{background:var(--test-d);text-decoration:none}
58	.btn.au{background:var(--audit);border-color:var(--audit)}.btn.au:hover{background:var(--audit-d)}
59	.cta{text-align:center;margin-top:40px}
60	
61	/* hero */
62	#hero{text-align:center;padding-top:clamp(28px,5vw,64px);position:relative;isolation:isolate}
63	#hero:before{content:"";position:absolute;z-index:-1;left:50%;top:-140px;width:min(1400px,140vw);height:760px;transform:translateX(-50%);pointer-events:none;background:radial-gradient(34% 42% at 28% 34%,oklch(84% .09 256/.42),transparent 72%),radial-gradient(30% 38% at 74% 28%,oklch(84% .1 295/.34),transparent 72%),radial-gradient(28% 34% at 52% 78%,oklch(90% .08 85/.32),transparent 72%)}
64	#hero .wrap>*{animation:rise 1s var(--ease) both}#hero .wrap>:nth-child(2){animation-delay:.06s}#hero .wrap>:nth-child(3){animation-delay:.12s}#hero .wrap>:nth-child(4){animation-delay:.18s}#hero .wrap>:nth-child(n+5){animation-delay:.24s}
65	@keyframes rise{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
66	#hero h1{max-width:13em;margin:0 auto;text-wrap:balance}
67	.lede{margin:18px auto 0;font-size:clamp(18px,2vw,21px);line-height:1.45;max-width:36em;color:var(--ink);text-wrap:balance}
68	.what{margin:8px auto 0;font-size:clamp(16px,1.7vw,18px);color:var(--mut);max-width:32em;text-wrap:balance}
69	.box{display:flex;gap:8px;align-items:center;margin:32px auto 0;max-width:640px;border-radius:16px;padding:7px 7px 7px 20px;background:var(--panel);border:1px solid var(--line);box-shadow:var(--lift)}
70	.box:focus-within{border-color:var(--test);box-shadow:0 0 0 3px var(--test-bg),var(--lift)}
71	.box input{flex:1;min-width:0;font:inherit;font-size:17px;border:0;background:none;color:var(--ink);padding:10px 0;outline:0}
72	.box input::placeholder{color:oklch(58% .01 255)}
73	.chips{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;margin-top:12px}
74	.chips .lbl{color:var(--mut);font-size:14px;align-self:center;margin-right:2px}
75	.chips button{background:var(--panel);color:var(--ink);border:1px solid var(--line);font-weight:500;font-size:14px;min-height:34px;padding:0 13px;border-radius:99px}
76	.chips button:hover{background:var(--hover);color:var(--test-d)}
77	.hint{color:var(--mut);font-size:13.5px;margin-top:8px;min-height:1.45em}
78	.hint.cached{color:var(--ok-d);font-weight:500}
79	
80	/* generated prompt */
81	#out{padding-top:28px}
82	.hit{padding:20px 22px;margin-bottom:16px}
83	.hit[hidden],.fresh[hidden]{display:none}
84	.hit-top{display:flex;flex-wrap:wrap;align-items:center;gap:6px 14px;color:var(--mut);font-size:14px}
85	.pill{display:inline-flex;align-items:center;gap:6px;font-weight:600;font-size:13px;border-radius:99px;padding:3px 11px;background:var(--ok-bg);color:var(--ok-d)}
86	.pill:before{content:"";width:7px;height:7px;border-radius:50%;background:currentColor}
87	.pill.other{background:var(--test-bg);color:var(--test-d)}
88	.hit h3{font-size:24px;line-height:1.15;margin-top:10px}
89	.hit p{color:var(--mut);margin-top:6px;max-width:40em}
90	.hit-act{display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px;margin-top:16px}
91	.hit-act span{color:var(--mut);font-size:14px}
92	.fresh{font-size:15px;color:var(--mut);font-weight:600;margin:0 0 8px 4px}
93	.panel{overflow:hidden}
94	.tabs{display:flex;gap:2px;padding:6px 8px 0;border-bottom:1px solid var(--line);align-items:flex-end}
95	.tabs [role=tab]{font-size:14px;font-weight:600;color:var(--mut);background:none;border:0;border-radius:8px 8px 0 0;padding:0 14px;min-height:40px}
96	.tabs [role=tab]:hover{color:var(--ink);background:none}
97	.tabs [role=tab][aria-selected=true]{color:var(--test-d);box-shadow:inset 0 -2px 0 var(--test)}
98	.tabs .sp{flex:1}
99	.tabs .cp{margin:0 2px 6px 0;min-height:34px;font-size:14px;padding:0 14px}
100	.how{padding:12px 20px 0;color:var(--mut);font-size:14px}
101	pre{white-space:pre-wrap;word-break:break-word;font-size:13.5px;line-height:1.6;padding:8px 20px 20px;max-height:400px;overflow:auto;color:var(--ink)}
102	.strip{list-style:none;padding:0;display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:14px}
103	.strip li{display:flex;gap:10px;align-items:center;font-size:14px;line-height:1.3;padding:12px 14px}
104	.strip li .ic{color:var(--test)}
105	.cli{padding:14px 18px;margin-top:10px;font-size:13.5px;line-height:1.8;overflow-x:auto;white-space:pre}
106	.cli .p,.cli .c{color:var(--mut)}.cli .p{user-select:none}
107	
108	/* film: full bleed, no frame, edges fade into the page */
109	#film{padding:clamp(32px,5vw,72px) 0 0}
110	.reel{position:relative;max-width:1680px;margin:0 auto;aspect-ratio:2/1}
111	.reel video{display:block;width:100%;height:100%;object-fit:cover;background:var(--bg);-webkit-mask-image:linear-gradient(90deg,transparent,#000 9%,#000 91%,transparent),linear-gradient(180deg,transparent,#000 11%,#000 89%,transparent);-webkit-mask-composite:source-in;mask-image:linear-gradient(90deg,transparent,#000 9%,#000 91%,transparent),linear-gradient(180deg,transparent,#000 11%,#000 89%,transparent);mask-composite:intersect;mix-blend-mode:multiply}
112	.ctl{position:absolute;right:max(20px,8%);bottom:9%;display:flex;gap:8px}
113	.ctl button{min-height:36px;padding:0 16px;font-size:13px;color:var(--ink);background:oklch(99.7% .0015 255/.92);border:1px solid var(--line);box-shadow:var(--lift)}
114	.ctl button:hover{background:var(--panel)}
115	
116	/* bands: one full-bleed color world per tool, so a new reader always knows which tool this is.
117	   A soft glow from the top edge plus a quiet dot field, masked so it fades out. */
118	.band{position:relative;isolation:isolate;margin-top:var(--pad);padding:clamp(64px,8vw,104px) 0;background:var(--tint);border-block:1px solid var(--edge);overflow:hidden}
119	.band+.band{margin-top:0;border-top:0}
120	.band:before,.band:after{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none}
121	.band:before{background:radial-gradient(90% 55% at 50% 0%,var(--glow),transparent 70%)}
122	.band:after{background-image:radial-gradient(circle,var(--dot) 1px,transparent 1.4px);background-size:24px 24px;-webkit-mask-image:radial-gradient(70% 50% at 50% 22%,#000,transparent 78%);mask-image:radial-gradient(70% 50% at 50% 22%,#000,transparent 78%)}
123	.b-test{--tint:oklch(96.4% .02 250);--glow:oklch(91% .06 252/.85);--dot:oklch(55% .19 256/.16);--edge:oklch(89.5% .04 252);--c:var(--test);--cd:var(--test-d);--link:var(--test-d)}
124	.b-audit{--tint:oklch(96.5% .022 300);--glow:oklch(91.5% .06 300/.85);--dot:oklch(52% .2 295/.15);--edge:oklch(89.5% .045 300);--c:var(--audit);--cd:var(--audit-d);--link:var(--audit-d)}
125	.b-rcpt{--tint:oklch(97.3% .026 85);--glow:oklch(93% .07 85/.9);--dot:oklch(60% .12 70/.16);--edge:oklch(90% .05 80);--c:var(--gold);--cd:var(--gold-d);--link:var(--gold-d)}
126	.eyebrow{display:flex;align-items:center;justify-content:center;gap:10px;margin-bottom:18px;font-weight:650;font-size:17px;letter-spacing:-.015em;color:var(--cd)}
127	.tile{width:34px;height:34px;border-radius:10px;background:var(--c);color:oklch(99.5% .003 256);display:grid;place-items:center;flex:none}
128	.tile .ic{width:19px;height:19px}
129	
130	/* three beats: a broken step, the fix, the proof */
131	.beats{list-style:none;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:clamp(18px,2.6vw,32px);margin-top:clamp(40px,5vw,60px);position:relative}
132	.beat{display:flex;flex-direction:column;gap:14px;min-width:0;position:relative}
133	.beat+.beat:before{content:"";position:absolute;left:calc(-1 * clamp(18px,2.6vw,32px));top:58px;width:clamp(18px,2.6vw,32px);height:2px;background:var(--edge)}
134	.bl{display:flex;align-items:center;justify-content:center;gap:10px;font-weight:650;font-size:17px;letter-spacing:-.02em;text-align:center}
135	.bn{width:26px;height:26px;border-radius:50%;flex:none;display:grid;place-items:center;font:600 13px/1 var(--mono);background:var(--c);color:oklch(99.5% .003 256)}
136	.win{flex:1;display:flex;flex-direction:column;overflow:hidden;text-align:left}
137	.win-h{display:flex;align-items:center;gap:6px;padding:10px 14px;border-bottom:1px solid var(--line);font-size:12.5px;color:var(--mut)}
138	.win-h i{width:9px;height:9px;border-radius:50%;background:var(--line);display:inline-block}
139	.win-h span{margin-left:6px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
140	.win-b{padding:16px 16px 18px;display:flex;flex-direction:column;gap:8px;font:500 14px/1.45 var(--mono);flex:1}
141	.ln{padding:5px 9px;border-radius:7px;overflow-wrap:anywhere}
142	.ln.cmd:before{content:"$ ";color:var(--mut)}
143	.ln.err{background:var(--bad-bg);color:var(--bad)}
144	.ln.del{background:var(--bad-bg);color:var(--bad);text-decoration:line-through;text-decoration-thickness:1px}
145	.ln.del:before{content:"\2212  ";text-decoration:none;display:inline-block;width:1.4em}
146	.ln.add{background:var(--ok-bg);color:var(--ok-d)}
147	.ln.add:before{content:"+  ";display:inline-block;width:1.4em}
148	.ln.note{font-family:Geist,sans-serif;font-size:13.5px;color:var(--mut);padding:2px 9px}
149	.pass{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;flex:1;padding:6px 0}
150	.pass b{font:700 clamp(26px,2.8vw,32px)/1 Geist,sans-serif;letter-spacing:-.035em;color:var(--ok-d)}
151	.dots{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;max-width:220px}
152	.dots i{width:16px;height:16px;border-radius:50%;background:var(--ok);display:grid;place-items:center}
153	.dots i:after{content:"";width:6px;height:3.5px;border:solid oklch(99.5% .003 150);border-width:0 0 1.8px 1.8px;transform:translateY(-1px) rotate(-45deg)}
154	.src{text-align:center;margin-top:26px;color:var(--mut);font-size:15px}
155	
156	/* the number line: plain sentences with the numbers set large */
157	.tally{display:flex;flex-wrap:wrap;justify-content:center;gap:12px clamp(28px,5vw,64px);margin-top:clamp(56px,7vw,88px);text-align:center}
158	.tally p{display:flex;flex-direction:column;align-items:center;gap:4px;font-size:16px;color:var(--mut)}
159	.tally b{font-size:clamp(44px,6vw,72px);line-height:1;font-weight:700;letter-spacing:-.05em;color:var(--cd);font-variant-numeric:tabular-nums}
160	
161	/* PR carousel */
162	.prs{margin-top:clamp(28px,4vw,40px)}
163	.track{--g:max(24px,calc(50vw - 516px));display:flex;gap:20px;overflow-x:auto;scroll-snap-type:x mandatory;scroll-padding:0 var(--g);padding:16px var(--g) 32px;margin:0 calc(50% - 50vw);scrollbar-width:none;overscroll-behavior-x:contain}
164	.track::-webkit-scrollbar{display:none}
165	.track:focus-visible{outline-offset:-6px;border-radius:24px}
166	.track>:first-child{margin-left:auto}.track>:last-child{margin-right:auto}
167	.pr{flex:0 0 min(330px,82vw);scroll-snap-align:start;display:flex;flex-direction:column;overflow:hidden;min-width:0;text-align:left;transition:transform .6s var(--ease),box-shadow .6s var(--ease)}
168	.pr:hover{transform:translateY(-4px);box-shadow:var(--lift-h)}
169	.cover{display:block;aspect-ratio:16/9;overflow:hidden;background:var(--sunk);border-bottom:1px solid var(--line)}
170	.cover img{width:100%;height:100%;object-fit:cover;object-position:top left;display:block}
171	.cover.ty{display:flex;flex-direction:column;justify-content:flex-end;gap:2px;padding:16px 18px;background:var(--test-bg);text-decoration:none;color:var(--test-d)}
172	.cover.ty b{font-size:44px;line-height:1;letter-spacing:-.05em}
173	.cover.ty span{font:500 13px var(--mono);color:var(--mut)}
174	.pr-b{padding:16px 18px 18px;display:flex;flex-direction:column;gap:8px;flex:1}
175	.pr-top{display:flex;align-items:center;gap:8px;min-width:0}
176	.repo{font:500 12.5px/1.2 var(--mono);color:var(--mut);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}
177	.st{margin-left:auto;font-weight:600;font-size:12px;border-radius:99px;padding:2px 9px 2px 8px;background:var(--ok-bg);color:var(--ok-d);display:inline-flex;align-items:center;gap:5px;flex:none;text-transform:capitalize}
178	.st:before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}
179	.st.merged{background:var(--audit-bg);color:var(--audit-d)}
180	.st.closed{background:var(--sunk);color:var(--mut)}
181	.pr h3{font-size:17px;line-height:1.3}
182	.pr h3 small{font:500 13px var(--mono);color:var(--mut);letter-spacing:0;white-space:nowrap}
183	.pr h3 a{color:var(--ink)}
184	.pr h3 a:hover{color:var(--test-d)}
185	.pr .fix{font-size:14px;color:var(--mut);line-height:1.45}
186	.pr-a{margin-top:auto;display:flex;flex-wrap:wrap;gap:6px 16px;padding-top:6px;font-size:14px;font-weight:600}
187	.ctrl{display:flex;align-items:center;justify-content:center;gap:16px}
188	.arw{width:44px;height:44px;min-height:0;padding:0;border-radius:50%;font-size:22px;line-height:1;color:var(--ink);background:var(--panel);border:1px solid var(--line);box-shadow:var(--sh)}
189	.arw:hover{background:var(--hover)}
190	.arw:disabled{opacity:.35;cursor:default}
191	.count{font:500 14px var(--mono);color:var(--mut);min-width:6.5em;text-align:center}
192	.empty{text-align:center;color:var(--mut);padding:28px 0}
