// Drive the headless shell over CDP: open a URL at a width, run a test script, print JSON.
// usage: node cdp.js <width> <height> <url> <test.js> [shot.png] [selector]
// env: DPR (device scale), WAIT (ms before test), NOJS=1 (disable JS), FULL=1 (full page shot)
const { spawn } = require("child_process");
const fs = require("fs"), path = require("path");
const { WebSocket } = require("D:/Atharva/Software/nodejs/npm/node_modules/undici");
const base = "C:/Users/AtharvaShah/AppData/Local/ms-playwright/chromium_headless_shell-1234";
const dir = fs.readdirSync(base).find(d => fs.existsSync(path.join(base, d, "chrome-headless-shell.exe")));
const CH = path.join(base, dir, "chrome-headless-shell.exe");
const [w, h, url, testFile, shot, sel] = process.argv.slice(2);
const port = 9300 + Math.floor(Math.random() * 500);
const prof = fs.mkdtempSync(path.join(require("os").tmpdir(), "cdp-"));
const p = spawn(CH, [`--remote-debugging-port=${port}`, `--user-data-dir=${prof}`, `--window-size=${w},${h}`, "--hide-scrollbars", "about:blank"], { stdio: "ignore" });
const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  let tabs;
  for (let i = 0; i < 50; i++) { try { tabs = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); break } catch { await sleep(200) } }
  const t = tabs.find(x => x.type === "page");
  const ws = new WebSocket(t.webSocketDebuggerUrl);
  await new Promise(r => ws.addEventListener("open", r));
  let id = 0; const pend = {}; const logs = [];
  ws.addEventListener("message", e => { const m = JSON.parse(e.data); if (m.id && pend[m.id]) { pend[m.id](m); delete pend[m.id] }
    if (m.method === "Runtime.exceptionThrown") logs.push("EXC " + JSON.stringify(m.params.exceptionDetails.exception && m.params.exceptionDetails.exception.description || m.params.exceptionDetails.text));
    if (m.method === "Runtime.consoleAPICalled" && /error|warn/.test(m.params.type)) logs.push(m.params.type + " " + m.params.args.map(a => a.value || a.description).join(" "));
    if (m.method === "Log.entryAdded" && m.params.entry.level === "error") logs.push("LOG " + m.params.entry.text + " " + (m.params.entry.url || "")); });
  const send = (method, params = {}) => new Promise(r => { const i = ++id; pend[i] = r; ws.send(JSON.stringify({ id: i, method, params })) });
  await send("Runtime.enable"); await send("Log.enable"); await send("Page.enable");
  await send("Emulation.setDeviceMetricsOverride", { width: +w, height: +h, deviceScaleFactor: +(process.env.DPR || 1), mobile: +w < 768 });
  if (process.env.NOJS) await send("Emulation.setScriptExecutionDisabled", { value: true });
  if (process.env.RM) await send("Emulation.setEmulatedMedia", { features: [{ name: "prefers-reduced-motion", value: "reduce" }] });
  await send("Page.navigate", { url });
  await sleep(+(process.env.WAIT || 3500));
