.b-tools{--tint:oklch(96.6% .005 255);--glow:oklch(99.2% .002 255/.9);--dot:oklch(35% .012 255/.10);--edge:oklch(90.8% .007 255);--c:var(--ink);--cd:var(--ink);--link:var(--test-d)}
.tt{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;max-width:760px;margin:clamp(36px,4.5vw,52px) auto 0}
.tt [role=tab]{display:flex;align-items:center;gap:14px;min-height:0;padding:14px 18px;border-radius:16px;background:oklch(98.4% .003 255/.7);border:1px solid var(--edge);color:var(--ink);font-weight:400;text-align:left;white-space:normal;box-shadow:none;transition:background .25s,box-shadow .35s var(--ease)}
.tt [role=tab]:hover{background:var(--panel)}
.tt [role=tab][aria-selected=true]{background:var(--panel);border-color:transparent;box-shadow:0 0 0 2px var(--ink),var(--lift)}
.tt img{width:44px;height:44px;border-radius:12px;border:1px solid var(--line);flex:none;background:var(--panel)}
.tt b{display:block;font-size:18px;letter-spacing:-.025em;line-height:1.2}
.tt small{display:block;font-size:14px;color:var(--mut);line-height:1.3;margin-top:2px}
.tp{margin-top:clamp(28px,3.5vw,40px)}
.role{text-align:center;font-size:clamp(18px,1.9vw,21px);line-height:1.4;letter-spacing:-.012em;max-width:34em;margin:0 auto;text-wrap:balance}
.ph{display:none}
.show{display:grid;grid-template-columns:minmax(0,1.62fr) minmax(0,1fr);gap:clamp(24px,3.4vw,44px);align-items:center;margin-top:clamp(24px,3vw,32px)}
.stg{position:relative;aspect-ratio:1400/780;border-radius:18px;overflow:hidden;background:var(--panel);border:1px solid var(--line);box-shadow:var(--lift)}
.shot{position:absolute;inset:0;display:block;background:var(--panel);opacity:0;visibility:hidden;transition:opacity .55s var(--ease),visibility 0s linear .55s}
.shot.on{opacity:1;visibility:visible;transition:opacity .55s var(--ease),visibility 0s}
.shot img{display:block;width:100%;height:100%;object-fit:contain}
.shot.dk{background:oklch(17.5% .004 255)}
.shot.pad img{padding:5%}
.shot:focus-visible{outline-offset:-4px;border-radius:18px}
.evs{list-style:none;padding:0;display:flex;flex-direction:column;gap:8px;counter-reset:ev}
.ev{border-radius:16px;padding:14px 16px 14px 14px;transition:background .25s,box-shadow .35s var(--ease)}
.ev:has([aria-pressed=true]){background:var(--panel);box-shadow:var(--lift)}
.ev:hover{background:var(--panel)}
.pk{display:grid;grid-template-columns:30px 1fr;gap:12px;align-items:start;width:100%;min-height:0;padding:0;border:0;border-radius:8px;background:none;color:var(--ink);font-weight:500;font-size:16.5px;line-height:1.4;letter-spacing:-.01em;text-align:left;white-space:normal;transition:none}
.pk:hover{background:none}
.pk:focus-visible{outline-offset:6px}
.pk .n{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;font:600 13px/1 var(--mono);border:1.5px solid oklch(72% .01 255);color:var(--mut);transition:background .25s,color .25s,border-color .25s}
.pk[aria-pressed=true] .n{background:var(--ink);border-color:var(--ink);color:oklch(99.5% .003 255)}
.ev .src2{display:inline-block;margin:6px 0 0 42px;font-size:14px;font-weight:600}
.ev figure{margin:0}
.cash text{font:500 12px Geist,sans-serif;fill:var(--mut)}
.cash .t{font-size:13.5px;font-weight:600;fill:var(--ink)}
.cash .g{stroke:var(--line);stroke-width:1}
.cash .z{stroke:oklch(70% .01 255);stroke-width:1.2;stroke-dasharray:3 4}
.cash .b{fill:none;stroke:var(--ok);stroke-width:3;stroke-linecap:round;stroke-linejoin:round}
.cash .o{fill:none;stroke:var(--bad);stroke-width:3;stroke-linecap:round;stroke-linejoin:round}
.cash .lb{fill:var(--ok-d);font-weight:600}.cash .lo{fill:var(--bad);font-weight:600}
.allp{text-align:center;margin-top:clamp(36px,4.5vw,52px);font-size:17px;font-weight:600}
/* no JS: every tool stacked, every screenshot shown with its caption */
html:not(.js) .tt{display:none}
html:not(.js) .tp+.tp{margin-top:clamp(56px,7vw,80px)}
html:not(.js) .ph{display:flex;align-items:center;justify-content:center;gap:12px;font-size:22px;font-weight:700;letter-spacing:-.025em;margin-bottom:12px}
html:not(.js) .ph img{width:40px;height:40px;border-radius:11px;border:1px solid var(--line)}
html:not(.js) .show{grid-template-columns:repeat(auto-fit,minmax(280px,1fr));align-items:start}
html:not(.js) .ev{background:var(--panel);box-shadow:var(--lift);padding:0;overflow:hidden}
html:not(.js) .shot{position:relative;opacity:1;visibility:visible;aspect-ratio:1400/780;border-bottom:1px solid var(--line)}
html:not(.js) .cap{display:grid;grid-template-columns:30px 1fr;gap:12px;padding:14px 16px 0;font-weight:500;line-height:1.4}
html:not(.js) .cap .n{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;font:600 13px/1 var(--mono);background:var(--ink);color:oklch(99.5% .003 255)}
html:not(.js) .ev .src2{margin:6px 16px 16px 58px}

