/* tools: tabs per tool. Inside a tab, the numbered proofs pick which screenshot fills the stage.
   Without JS the markup already shows every tool and every screenshot, stacked. */
(function(){
 var root=$("tools");if(!root)return;
 var tabs=Array.prototype.slice.call(root.querySelectorAll("[role=tab]"));
 var panels=tabs.map(function(t){return $(t.getAttribute("aria-controls"))});
 function pick(p,i,focus){
  var sh=p._shots,bt=p._btns;
  for(var k=0;k<sh.length;k++){
   var on=k===i;
   sh[k].classList.toggle("on",on);
   if(on)sh[k].removeAttribute("aria-hidden");else sh[k].setAttribute("aria-hidden","true");
   bt[k].setAttribute("aria-pressed",on?"true":"false");
  }
  if(focus)bt[i].focus();
 }
 panels.forEach(function(p){
  var show=p.querySelector(".show"),stg=document.createElement("div");
  stg.className="stg";p._shots=[];p._btns=[];
  Array.prototype.forEach.call(p.querySelectorAll(".ev"),function(li,i){
   var s=li.querySelector(".shot"),cap=li.querySelector(".cap"),b=document.createElement("button");
   s.id=p.id+"-shot"+(i+1);stg.appendChild(s);p._shots.push(s);
   b.type="button";b.className="pk";b.setAttribute("aria-controls",s.id);
   while(cap.firstChild)b.appendChild(cap.firstChild);
   cap.parentNode.replaceChild(b,cap);p._btns.push(b);
   b.addEventListener("click",function(){pick(p,i)});
   b.addEventListener("keydown",function(e){
    var n=p._btns.length,j=e.key==="ArrowDown"?(i+1)%n:e.key==="ArrowUp"?(i+n-1)%n:-1;
    if(j>=0){e.preventDefault();pick(p,j,true)}});
   /* a click anywhere on the row, except its source link, picks it */
   li.addEventListener("click",function(e){if(!e.target.closest("a,button"))pick(p,i)});
  });
  show.insertBefore(stg,show.firstChild);
  pick(p,0);
 });
 function sel(i,focus,push){
  tabs.forEach(function(t,k){var on=k===i;t.setAttribute("aria-selected",on?"true":"false");t.tabIndex=on?0:-1;panels[k].hidden=!on});
  if(focus)tabs[i].focus();
  if(push&&history.replaceState)history.replaceState(null,"","#"+panels[i].id);
 }
 tabs.forEach(function(t,i){
  t.addEventListener("click",function(){sel(i,false,true)});
  /* warm the next tab's screenshots on intent, so the switch shows them at once */
  t.addEventListener("pointerenter",function(){Array.prototype.forEach.call(panels[i].querySelectorAll("img[loading=lazy]"),function(m){m.loading="eager"})},{once:true});
 });
 root.querySelector("[role=tablist]").addEventListener("keydown",function(e){
  var i=tabs.indexOf(document.activeElement),n=tabs.length,j=-1;if(i<0)return;
  if(e.key==="ArrowRight")j=(i+1)%n;else if(e.key==="ArrowLeft")j=(i+n-1)%n;else if(e.key==="Home")j=0;else if(e.key==="End")j=n-1;
  if(j>=0){e.preventDefault();sel(j,true,true)}});
 /* deep links: #tools-entire opens the Entire tab and brings the section into view */
 function fromHash(scroll){
  var h=location.hash.slice(1);if(h==="tools-cfo")h="tools-cfoai";
  for(var i=0;i<panels.length;i++)if(panels[i].id===h){sel(i);if(scroll)root.scrollIntoView({block:"start"});return}
 }
 sel(0);fromHash(false);
 if(/^#tools-/.test(location.hash))addEventListener("load",function(){fromHash(true)});
 addEventListener("hashchange",function(){fromHash(true)});
})();

/* reveal: each block fades and rises once as it enters, staggered inside its group */

