// open a tab (window.__TAB) and a pick (window.__PICK), report layout facts, clip to the section
const root=document.getElementById("tools");
document.querySelectorAll(".rv").forEach(e=>e.classList.add("in"));
const tabs=[...root.querySelectorAll("[role=tab]")];
if(window.__TAB!=null)tabs[window.__TAB].click();
const p=root.querySelector("[role=tabpanel]:not([hidden])");
if(window.__PICK!=null)p.querySelectorAll(".pk")[window.__PICK].click();
if(window.__FOCUS){tabs[0].focus();const ev=new KeyboardEvent("keydown",{key:"ArrowRight",bubbles:true});tabs[0].dispatchEvent(ev);}
root.scrollIntoView({block:"start"});
await new Promise(r=>setTimeout(r,1500));
const imgs=[...root.querySelectorAll("img")].filter(i=>i.offsetParent!==null||i.closest(".shot.on"));
const r=root.getBoundingClientRect();
return {clip:{x:0,y:r.top+scrollY,width:innerWidth,height:r.height},
 sideways:document.documentElement.scrollWidth-innerWidth,
 hash:location.hash, sel:tabs.map(t=>t.getAttribute("aria-selected")).join(","),
 active:document.activeElement&&document.activeElement.id,
 shown:[...p.querySelectorAll(".shot")].map(s=>s.classList.contains("on")?"ON":"-").join(""),
 broken:[...root.querySelectorAll(".shot.on img")].filter(i=>i.complete&&i.naturalWidth===0).length,
 h:Math.round(r.height)};

